    drawCharacter(ctx, type, dir, walkFrame, x, y) {
        const key = `char_${type}_${dir}_${walkFrame}`;
        if (!this.cache[key]) {
            const pat = this.getCharacterPattern(type, dir, walkFrame);
            if (pat) {
                this.cache[key] = this.buildPattern(pat.pal, pat.data, 2);
            }
        }
        if (this.cache[key]) {
            ctx.drawImage(this.cache[key], x, y, this.tileSize, this.tileSize);
        }
    }

